import{_ as t,o as h,c as i,a2 as a}from"./chunks/framework.BBd5PKnH.js";const d=JSON.parse('{"title":"Bốn Phẩm Chất Trong Chiêm Tinh Học (Essential Dignities)","description":"","frontmatter":{},"headers":[],"relativePath":"astro/note_3.md","filePath":"astro/note_3.md"}'),c={name:"astro/note_3.md"};function g(o,n,r,u,e,l){return h(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="bon-pham-chat-trong-chiem-tinh-hoc-essential-dignities" tabindex="-1">Bốn Phẩm Chất Trong Chiêm Tinh Học (Essential Dignities) <a class="header-anchor" href="#bon-pham-chat-trong-chiem-tinh-hoc-essential-dignities" aria-label="Permalink to &quot;Bốn Phẩm Chất Trong Chiêm Tinh Học (Essential Dignities)&quot;">​</a></h1><p>Khi một hành tinh nằm trong một cung nào đó trên bản đồ sao của bạn, vị trí đó có thể ảnh hưởng đến độ mạnh hay yếu của hành tinh ấy. Nói cách khác, mỗi hành tinh trong bản đồ sao vẫn luôn tác động đến bạn, nhưng cường độ của nó thay đổi tùy vào việc nó có đang ở vị trí phù hợp với mình hay không. Chiêm tinh học cổ điển phân loại điều này theo <strong>bốn phẩm chất</strong> sau:</p><ul><li><strong>Tướng (Domicile)</strong>: hành tinh ở đúng cung mà nó chủ quản — đây là &quot;nhà&quot; của nó, nơi nó thể hiện rõ nhất bản chất và có nhiều nguồn lực nhất để hoạt động.</li><li><strong>Tù (Detriment)</strong>: hành tinh ở cung đối đỉnh với cung mà nó chủ quản — vị trí này khiến hành tinh phải hoạt động theo cách xa lạ với bản chất của nó, nên thường bộc lộ khó khăn hoặc mâu thuẫn nội tại.</li><li><strong>Vượng (Exaltation)</strong>: vị trí mà hành tinh thể hiện tốt nhất — cung thuận lợi nhất cho năng lượng của nó, nơi phẩm chất của hành tinh được nâng lên, tôn vinh.</li><li><strong>Hãm (Fall)</strong>: hành tinh ở cung đối đỉnh với cung Vượng của nó — đây là vị trí hành tinh thể hiện yếu nhất, dễ bị lu mờ hoặc khó phát huy.</li></ul><h2 id="vi-du-minh-hoa-sao-hoa" tabindex="-1">Ví dụ minh họa: Sao Hỏa <a class="header-anchor" href="#vi-du-minh-hoa-sao-hoa" aria-label="Permalink to &quot;Ví dụ minh họa: Sao Hỏa&quot;">​</a></h2><p>Vì Sao Hỏa là chủ quản của Bạch Dương, nên:</p><ul><li>Sao Hỏa ở vị trí <strong>Tướng</strong> khi nằm ở cung Bạch Dương.</li><li>Sao Hỏa ở vị trí <strong>Tù</strong> (yếu nhất theo nghĩa &quot;lạc nhà&quot;) khi nằm ở cung đối đỉnh với Bạch Dương là <strong>Thiên Bình</strong>.</li><li>Sao Hỏa ở vị trí <strong>Vượng</strong> (mạnh mẽ nhất) khi nằm ở cung <strong>Ma Kết</strong>.</li><li>Sao Hỏa ở vị trí <strong>Hãm</strong> (yếu nhất theo nghĩa &quot;mất sức&quot;) khi nằm ở cung đối đỉnh với Ma Kết là <strong>Cự Giải</strong>.</li></ul><h2 id="đung-lo-lang-neu-hanh-tinh-cua-ban-o-vi-tri-tu-hay-ham" tabindex="-1">Đừng lo lắng nếu hành tinh của bạn ở vị trí Tù hay Hãm <a class="header-anchor" href="#đung-lo-lang-neu-hanh-tinh-cua-ban-o-vi-tri-tu-hay-ham" aria-label="Permalink to &quot;Đừng lo lắng nếu hành tinh của bạn ở vị trí Tù hay Hãm&quot;">​</a></h2><p>Đừng cảm thấy nản lòng nếu một trong những hành tinh của bạn ở vị trí Tù hay Hãm. Mặt Trăng ở Bọ Cạp và Sao Hỏa ở Thiên Bình của chính tôi đều ở những vị trí bất lợi nhất có thể, và điều đó chưa bao giờ ngăn cản tôi. Ngay cả những vị trí hành tinh thể hiện yếu nhất cũng vẫn mang những ý nghĩa quan trọng đối với bạn — chúng chỉ cho thấy hành tinh đó cần bạn nỗ lực nhiều hơn để làm chủ năng lượng của nó, chứ không có nghĩa là năng lượng ấy biến mất.</p><p>Hơn nữa, bạn còn có nhiều vị trí khác trong bản đồ sao mang đến những thuận lợi riêng. Cũng cần lưu ý rằng chỉ có <strong>bảy hành tinh nhìn thấy được bằng mắt thường</strong> (Mặt Trời, Mặt Trăng, Sao Thủy, Sao Kim, Sao Hỏa, Sao Mộc, Sao Thổ) mới được phân loại đầy đủ theo hệ thống Tù/Hãm trong chiêm tinh học cổ điển; các hành tinh hiện đại (Thiên Vương, Hải Vương, Diêm Vương) được bổ sung sau này và có phần chồng lấn với các chủ quản truyền thống.</p><p>Hãy nhớ rằng, các phẩm chất này không phải là điều đáng lo ngại. Tất cả các hành tinh đều có ảnh hưởng đến bạn, dù chúng đang thể hiện ở trạng thái mạnh mẽ toàn diện hay đang gặp khó khăn — cả hai đều là một phần ý nghĩa trong bản đồ sao của bạn.</p><h2 id="bang-chu-quan-cac-cung-rulerships" tabindex="-1">Bảng chủ quản các cung (Rulerships) <a class="header-anchor" href="#bang-chu-quan-cac-cung-rulerships" aria-label="Permalink to &quot;Bảng chủ quản các cung (Rulerships)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cung (Sign)</th><th>Hành tinh chủ quản (Ruler)</th></tr></thead><tbody><tr><td>Bạch Dương (Aries)</td><td>Sao Hỏa (Mars)</td></tr><tr><td>Kim Ngưu (Taurus)</td><td>Sao Kim (Venus)</td></tr><tr><td>Song Tử (Gemini)</td><td>Sao Thủy (Mercury)</td></tr><tr><td>Cự Giải (Cancer)</td><td>Mặt Trăng (Moon)</td></tr><tr><td>Sư Tử (Leo)</td><td>Mặt Trời (Sun)</td></tr><tr><td>Xử Nữ (Virgo)</td><td>Sao Thủy (Mercury)</td></tr><tr><td>Thiên Bình (Libra)</td><td>Sao Kim (Venus)</td></tr><tr><td>Bọ Cạp (Scorpio)</td><td>Sao Diêm Vương (Pluto, hiện đại), Sao Hỏa (Mars, cổ điển)</td></tr><tr><td>Nhân Mã (Sagittarius)</td><td>Sao Mộc (Jupiter)</td></tr><tr><td>Ma Kết (Capricorn)</td><td>Sao Thổ (Saturn)</td></tr><tr><td>Bảo Bình (Aquarius)</td><td>Sao Thiên Vương (Uranus, hiện đại), Sao Thổ (Saturn, cổ điển)</td></tr><tr><td>Song Ngư (Pisces)</td><td>Sao Hải Vương (Neptune, hiện đại), Sao Mộc (Jupiter, cổ điển)</td></tr></tbody></table><blockquote><p><strong>Cách suy ra Tù, Vượng, Hãm từ bảng trên</strong>: với mỗi hành tinh, cung Tướng là cung nó chủ quản trong bảng; cung Tù là cung đối đỉnh (cách 6 cung) với cung Tướng; cung Vượng là cung riêng theo truyền thống (ví dụ Sao Hỏa Vượng ở Ma Kết); cung Hãm là cung đối đỉnh với cung Vượng.</p></blockquote>',13)])])}const m=t(c,[["render",g]]);export{d as __pageData,m as default};
